// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 _amount, address _user) public {
        vm.assume(_amount > 0);
        vm.assume(_user != address(0));
        vm.assume(_amount < type(uint256).max);
        vm.deal(_user, _amount);
        uint256 prev = c.getBalance(_user);
        vm.prank(_user);
        c.addToBalance{value: _amount}();
        uint256 afterCall = c.getBalance(_user);
        assertTrue(afterCall == prev + _amount);
    }
}
